"""Protocol tests: known answers from the original Java code + fake device."""
from __future__ import annotations

from datetime import datetime

from po3m.protocol import (
    APP_KEY, PRIME_P, Cipher, Po3mSession, aes_ctr, algorithms, crc32,
    decode_battery, decode_device_info, decode_history_chunk, decode_live, modes,
    xxtea_decrypt, xxtea_encrypt,
)

from fake_po3m import FakePO3M

# Generated by running the decompiled XXTEA2 / ProtocolParser.a / AuthCommand.g
JAVA = dict(line.split() for line in """
R1 030a11181f262d343b424950575e656c
K 429c010e135204da90286d22b6a8af0244b34db0
R1p ca8e4017ac1a9513c33a81f1b2ad278cc812a189
back 030a11181f262d343b424950575e656c
R2p e31e2d5e16160a6db3aafb0e600b5c2374aff4c3
key2 fdcdeb2f39bdeff0e302bd5c1bedcded
ctr 41f0babbd624067b23b364c183a9b3d0b4460f2969a5ea9f4fce50478ec85f73b6f4296903
crc 4b46c5fa
cbc 076815f05783b1866469ed50c3256a76047a19dcc61f362394e8bf5a1584590164b48767177a45043e5489d7b660d6ecbbe0ee45f570e7410e95658bba9eeb80
""".strip().splitlines())


def seq(n, a, m):
    return bytes((a + i * m) & 0xFF for i in range(n))


def test_known_answers_from_java():
    r1 = bytes(b if b < 128 else (256 - b) & 0xFF for b in seq(16, 3, 7))
    r2, dev_id = seq(16, 0x41, 13), seq(16, 0x10, 29)
    k = xxtea_encrypt(dev_id, APP_KEY)
    r1p = xxtea_encrypt(r1, k)
    r2p = xxtea_encrypt(r2, k)
    key2 = Cipher(algorithms.AES(k[:16]), modes.ECB()).encryptor().update(r2p[:16])
    data = seq(37, 0x55, 3)
    k1, iv1 = r1[:8] + PRIME_P[:8], r1[8:] + PRIME_P[8:]
    cbc = Cipher(algorithms.AES(k1), modes.CBC(iv1)).encryptor().update(seq(64, 0xFB, 5))
    assert r1.hex() == JAVA["R1"]
    assert k.hex() == JAVA["K"]
    assert r1p.hex() == JAVA["R1p"]
    assert xxtea_decrypt(r1p, k).hex() == JAVA["back"]
    assert r2p.hex() == JAVA["R2p"]
    assert key2.hex() == JAVA["key2"]
    assert aes_ctr(data, key2, r2[:12], 0x12345678).hex() == JAVA["ctr"]
    assert f"{crc32(data):08x}" == JAVA["crc"]
    assert cbc.hex() == JAVA["cbc"]


def test_tx_frame_layout_matches_java(monkeypatch):
    # Frames produced by ProtocolWrapper.i() with an XOR-0x5A "cipher" stub
    import po3m.protocol as proto

    monkeypatch.setattr(proto, "aes_ctr", lambda d, k, n, s: bytes(b ^ 0x5A for b in d))
    s = Po3mSession()
    s.key2, s.nonce, s.tx_count = b"x" * 16, bytes(12), 0x1000
    assert s.build_frame(bytes([0xFA]) + bytes(range(1, 17))).hex() == (
        "b0110010fa0102030405060708090a0b0c0d0e0f10dbe00cc000000000da"
    )
    assert s.tx_count == 0x1000
    assert s.build_frame(b"\x50").hex() == "b00100010a23e433e301100000ea"
    assert s.tx_count == 0x1002
    assert s.build_frame(bytes([0x21, 26, 11, 22, 18, 37, 0])).hex() == (
        "b00700077b40514c487f5a5a0842f903100000e7"
    )
    assert s.tx_count == 0x1004


def _session_with_device():
    dev = FakePO3M()
    msgs = []
    sess = Po3mSession(writer=dev.write, on_message=lambda c, d: msgs.append((c, d)))

    def pump():
        while dev.out:
            sess.feed(dev.out.pop(0))

    sess.start_auth()
    pump()
    return dev, sess, msgs, pump


def test_handshake_and_commands():
    dev, sess, msgs, pump = _session_with_device()
    assert sess.authenticated
    assert sess.device_id == dev.dev_id
    for cmd in (0x22, 0x25, 0x50, 0x40, 0x41):
        sess.send(bytes([cmd]))
        pump()
    got = dict((c, d) for c, d in msgs)
    assert decode_battery(got[0x22]) == {"battery_status": 0, "battery": 87}
    info = decode_device_info(got[0x25])
    assert info["firmware"] == "1.0.2" and info["serial"] == "ABCDEF123456"
    assert info["time"] == datetime(2026, 11, 22, 18, 30, 0)
    lives = [decode_live(d) for c, d in msgs if c == 0x52]
    assert [(l.spo2, l.pulse_rate) for l in lives] == [(97, 62), (98, 63), (98, 64)]
    assert lives[0].perfusion_index == 3.0 and lives[0].pulse_wave == [1000, 1200, 1100]
    more, recs = decode_history_chunk(got[0x41])
    assert not more and len(recs) == 2
    assert recs[1].timestamp == datetime(2026, 11, 21, 9, 30, 5)
    assert (recs[1].spo2, recs[1].pulse_rate, recs[1].perfusion_index) == (99, 58, 5.2)


def test_r1_mismatch_is_rejected():
    import pytest
    from po3m.protocol import Po3mError

    dev = FakePO3M()
    sess = Po3mSession(writer=dev.write)
    sess.start_auth()
    sess.r1 = bytes(16)  # the device answers for another R1 -> must be refused
    with pytest.raises(Po3mError, match="R1 mismatch"):
        for chunk in dev.out:
            sess.feed(chunk)


def test_live_filters():
    assert decode_live(bytes([101, 60, 0, 1, 0, 1, 0, 0, 0])) is None  # SpO2 > 100
    assert decode_live(bytes([98, 60])) is None  # too short
    # PI out of range keeps the previous value
    assert decode_live(bytes([98, 60, 5, 0, 0, 100, 0, 0, 0]), 2.5).perfusion_index == 2.5
